package dev.pocketengine.browser;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.UUID;
import java.util.concurrent.*;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

/** Actual bounded private draft file/CAS. Not Android process-death, IME or visual acceptance. */
public final class BrowserResearchDraftStoreTest {
    File file()throws Exception{return new File(Files.createTempDirectory("browser-goal-draft-").toFile(),"browser/research-goals.json");}
    @Test public void absentDraftIsEmptyAndNeverStartsOrRestoresConsent()throws Exception {JSONObject read=new BrowserResearchDraftStore(file()).read("owner-default","");assertEquals("",read.getString("text"));assertEquals(0,read.getLong("revision"));assertFalse(read.getBoolean("executionAuthorized"));assertTrue(read.getBoolean("draftOnly"));}
    @Test public void exactChineseEmojiWhitespaceSurvivesReopeningAndOnlyAllowedMetadataIsOnDisk()throws Exception {File file=file();BrowserResearchDraftStore store=new BrowserResearchDraftStore(file);String goal="  比较🙂原文\n保留三页依据  ";JSONObject saved=store.save("owner-default","",0,goal);assertEquals(goal,new BrowserResearchDraftStore(file).read("owner-default","").getString("text"));assertTrue(saved.getLong("updatedAt")>0);JSONObject disk=new JSONObject(Files.readString(file.toPath()));assertEquals(3,disk.length());assertEquals(4,disk.getJSONArray("drafts").getJSONObject(0).length());for(String forbidden:new String[]{"consent","grant","cookie","runId","browserSessionId","approvalId"})assertFalse(disk.toString().contains(forbidden));}
    @Test public void profileAndOriginalTaskAreSeparateDraftContextsWithoutCopyingText()throws Exception {BrowserResearchDraftStore store=new BrowserResearchDraftStore(file());String task=UUID.randomUUID().toString(),other="profile-"+UUID.randomUUID();store.save("owner-default",task,0,"原任务目标");assertEquals("",store.read("owner-default","").getString("text"));assertEquals("",store.read(other,task).getString("text"));assertEquals("",store.read("owner-default",UUID.randomUUID().toString()).getString("text"));assertEquals("原任务目标",store.read("owner-default",task).getString("text"));}
    @Test public void staleEditorCannotReplaceANewerGoalOrReviveAnExplicitlyClearedGoal()throws Exception {BrowserResearchDraftStore store=new BrowserResearchDraftStore(file());store.save("owner-default","",0,"old");store.save("owner-default","",1,"new");assertThrows(Exception.class,()->store.save("owner-default","",1,"late old editor"));JSONObject cleared=store.save("owner-default","",2,"");assertEquals(3,cleared.getLong("revision"));assertThrows(Exception.class,()->store.save("owner-default","",2,"revived"));assertEquals("",store.read("owner-default","").getString("text"));}
    @Test public void clearEvenAnEmptyProfileFencesPreviouslyUnwrittenEditors()throws Exception {BrowserResearchDraftStore store=new BrowserResearchDraftStore(file());store.clearProfile("owner-default");assertEquals(1,store.read("owner-default","").getLong("revision"));assertThrows(Exception.class,()->store.save("owner-default","",0,"old pending edit"));}
    @Test public void clearingOneProfilePreservesOtherContextsButFencesOldRevisions()throws Exception {BrowserResearchDraftStore store=new BrowserResearchDraftStore(file());String profile="profile-"+UUID.randomUUID();store.save("owner-default","",0,"A");store.save(profile,"",1,"B");store.clearProfile("owner-default");assertEquals("",store.read("owner-default","").getString("text"));assertEquals("B",store.read(profile,"").getString("text"));assertThrows(Exception.class,()->store.save("owner-default","",2,"late"));}
    @Test public void multipleLiveInstancesSharingTheCanonicalPathHaveOneAtomicCasWinner()throws Exception {File f=file();BrowserResearchDraftStore a=new BrowserResearchDraftStore(f),b=new BrowserResearchDraftStore(new File(f.getParentFile(),"./research-goals.json"));ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{Callable<Boolean> first=()->{start.await();try{a.save("owner-default","",0,"A");return true;}catch(IllegalStateException stale){return false;}};Callable<Boolean> second=()->{start.await();try{b.save("owner-default","",0,"B");return true;}catch(IllegalStateException stale){return false;}};Future<Boolean> one=pool.submit(first),two=pool.submit(second);start.countDown();assertNotEquals(one.get(2,TimeUnit.SECONDS),two.get(2,TimeUnit.SECONDS));assertEquals(1,a.read("owner-default","").getLong("revision"));}finally{pool.shutdownNow();pool.awaitTermination(2,TimeUnit.SECONDS);}}
    @Test public void brokenOrForeignMetadataIsNotResetOrSilentlyTurnedIntoEmptyDraft()throws Exception {File file=file();file.getParentFile().mkdirs();String bad="{\"version\":2,\"revision\":1,\"drafts\":[]}";Files.writeString(file.toPath(),bad);BrowserResearchDraftStore store=new BrowserResearchDraftStore(file);assertThrows(Exception.class,()->store.read("owner-default",""));assertThrows(Exception.class,()->store.save("owner-default","",0,"replacement"));assertEquals(bad,Files.readString(file.toPath()));}
    @Test public void unknownPersistedConsentFieldMakesTheOriginalFileUnavailableNotAuthorized()throws Exception {File file=file();BrowserResearchDraftStore store=new BrowserResearchDraftStore(file);store.save("owner-default","",0,"goal");JSONObject state=new JSONObject(Files.readString(file.toPath()));state.getJSONArray("drafts").getJSONObject(0).put("consent",true);Files.writeString(file.toPath(),state.toString());assertThrows(Exception.class,()->store.read("owner-default",""));assertTrue(Files.readString(file.toPath()).contains("consent"));}
    @Test public void draftCountIsBoundedWithoutSilentlyEvictingUserTextAndClearReleasesCapacity()throws Exception {BrowserResearchDraftStore store=new BrowserResearchDraftStore(file());String first=null;for(int i=0;i<64;i++){String task=UUID.randomUUID().toString();if(first==null)first=task;store.save("owner-default",task,i,"goal"+i);}String extra=UUID.randomUUID().toString();assertThrows(Exception.class,()->store.save("owner-default",extra,64,"new"));assertEquals("goal0",store.read("owner-default",first).getString("text"));store.save("owner-default",first,64,"");store.save("owner-default",extra,65,"new");assertEquals("new",store.read("owner-default",extra).getString("text"));}
    @Test public void invalidIdentityOverlongInputAndUnpairedUnicodeCannotOverwriteTheOriginal()throws Exception {BrowserResearchDraftStore store=new BrowserResearchDraftStore(file());store.save("owner-default","",0,"original");assertThrows(Exception.class,()->store.read("other-browser-cookie", ""));assertThrows(Exception.class,()->store.read("owner-default","arbitrary-task"));assertThrows(Exception.class,()->store.save("owner-default","",1,"x".repeat(4001)));assertThrows(Exception.class,()->store.save("owner-default","",1,"\ud83d"));assertEquals("original",store.read("owner-default","").getString("text"));}
    @Test public void oversizedInputFileAndTemporaryWriteFailureDoNotClaimSavedOrDeleteOriginals()throws Exception {File file=file();file.getParentFile().mkdirs();Files.write(file.toPath(),new byte[BrowserResearchDraftStore.MAX_BYTES+1]);assertThrows(Exception.class,()->new BrowserResearchDraftStore(file).read("owner-default",""));File parent=Files.createTempFile("browser-goal-parent-",".file").toFile();Files.writeString(parent.toPath(),"keep");assertThrows(Exception.class,()->new BrowserResearchDraftStore(new File(parent,"research.json")).save("owner-default","",0,"not saved"));assertEquals("keep",Files.readString(parent.toPath()));}

    @Test public void nativePathRegistryStronglyKeepsTheSameLockAcrossReleasedAndFreshEditorsThenRacingCas()throws Exception {
        File file=file();BrowserResearchDraftStore first=new BrowserResearchDraftStore(new File(new String(file.getPath()))),surviving=new BrowserResearchDraftStore(new File(new String(file.getPath())));
        java.lang.reflect.Field locks=BrowserResearchDraftStore.class.getDeclaredField("LOCKS"),guard=BrowserResearchDraftStore.class.getDeclaredField("lock");locks.setAccessible(true);guard.setAccessible(true);
        java.util.Map<?,?> registry=(java.util.Map<?,?>)locks.get(null);assertTrue("Stable process registry owns strong canonical path keys",registry instanceof java.util.concurrent.ConcurrentMap);Object originalLock=guard.get(first);assertSame(originalLock,registry.get(file.getCanonicalPath()));assertSame(originalLock,guard.get(surviving));
        first.save("owner-default","",0,"original");first=null;System.gc();
        BrowserResearchDraftStore fresh=new BrowserResearchDraftStore(new File(file.getParentFile(),"./research-goals.json"));assertSame(originalLock,guard.get(fresh));assertSame(originalLock,registry.get(file.getCanonicalPath()));
        ExecutorService workers=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);
        try{Future<Boolean> a=workers.submit(()->{start.await();try{surviving.save("owner-default","",1,"surviving editor");return true;}catch(IllegalStateException stale){return false;}});Future<Boolean> b=workers.submit(()->{start.await();try{fresh.save("owner-default","",1,"fresh editor");return true;}catch(IllegalStateException stale){return false;}});start.countDown();assertNotEquals(a.get(2,TimeUnit.SECONDS),b.get(2,TimeUnit.SECONDS));assertEquals(2,fresh.read("owner-default","").getLong("revision"));}
        finally{workers.shutdownNow();workers.awaitTermination(2,TimeUnit.SECONDS);}
    }
}
